  "discourse_particles": [
   {"form":"hema","function":"hesitation; holding the floor (\"well…\", \"um\")","positions":"clause-initial; between constituents; standalone","register":"everyday (also poetic for hesitant speech; not sacred)","examples":[{"liraasa":"Hema… maivo ne sabesia.","english":"Well… I don't know."},{"liraasa":"Taivo futu relnura ki? — Hema. Poye.","english":"Will you come back? — Well. Maybe."},{"liraasa":"Maivo vurlova, hema, baba cupa de miru.","english":"I'd like, um, a cup of water."},{"liraasa":"Hema, hema… li bumre ne keleka.","english":"Well, well… the bread isn't rising."}],"id":"dp_hema_0001"},
   {"form":"nido","function":"self-repair: cancels the speaker's own preceding word, phrase or clause and replaces it (\"I mean\", \"rather\", \"no —\")","positions":"immediately after the abandoned item and before its replacement; or clause-initial to reformulate a whole previous utterance","register":"everyday; poetic (escalating correctio)","examples":[{"liraasa":"Maivo po bumreba tressa, nido, cuara bumreri.","english":"I baked three, I mean, four loaves."},{"liraasa":"Taivo ka benasan. Nido, taivo ka ruli benasan.","english":"You're good. I mean, you're very good."},{"liraasa":"Maivo amora taivo, nido, maivo devoda taivo.","english":"I love you, no, I pledge myself to you."},{"liraasa":"Maivo po bumreba ne tressa, nara cuara bumreri.","english":"I baked not three but four loaves. (corrective negation, for contrast)"}],"id":"dp_nido_0002"},
   {"form":"yori","function":"topic return / closure (\"anyway\", \"at any rate\"); with a possessive seno phrase, resumption (\"as I was saying\")","positions":"clause-initial; standalone","register":"everyday","examples":[{"liraasa":"Yori. Li bumre keleka ki?","english":"Anyway. Is the bread rising?"},{"liraasa":"Yori, maivo de seno: li bumrepago nedunia cono.","english":"As I was saying: the bakery needs coins."},{"liraasa":"Yori, taivo de seno. Taivo po senosia fime pilo po lenila maivo.","english":"Back to what you were saying. You said father heard me."},{"liraasa":"Yori.","english":"Whatever. / Anyway."}],"id":"dp_yori_0003"},
   {"form":"zoke","function":"irony / sarcasm: the speaker does not endorse, or mocks, the proposition","positions":"clause-final, in the attitude slot (instead of seye/mufe/poye/pifu); may precede ki; standalone","register":"everyday only","examples":[{"liraasa":"Dorin milobema toda-krono, zoke.","english":"Dorin smiles all the time. (Sure he does.)"},{"liraasa":"Ola ka li bumreasasan, zoke.","english":"That is divinely bready. (Oh, sure.)"},{"liraasa":"Zoke.","english":"Oh, sure. (eye-roll)"},{"liraasa":"Taivo po bumreba eli, zoke ki?","english":"YOU baked this, did you?"},{"liraasa":"Taivo ka ruli pamlonasan, zoke. — Ne zoke. Vera.","english":"You're very impatient, sure. — Not sure. True."}],"id":"dp_zoke_0004"}
  ]
